const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([50.282684, -58.944881]);
  const point2 = ee.Geometry.Point([50.415337, -54.128047]);
  const date = '2019-09-01';
  const dateStart = ee.Date(date);
  const dateEnd = dateStart.advance(3, 'day');

  // 2. Data Acquisition
  const collection = ee.ImageCollection('COPERNICUS/S2')
    .filterDate(dateStart, dateEnd)
    .filterBounds(point1.union(point2));

  const size = await collection.size().getInfo();
  console.log(`Total images found: ${size}`);

  if (size === 0) {
    console.log('No Sentinel-2 images found. Trying wider date range...');
    const dateEnd2 = dateStart.advance(7, 'day');
    const collection2 = ee.ImageCollection('COPERNICUS/S2')
      .filterDate(dateStart, dateEnd2)
      .filterBounds(point1.union(point2));

    const size2 = await collection2.size().getInfo();
    if (size2 === 0) {
      console.log('No data available.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudMask = qa.bitwiseAnd(1 << 10).eq(0)
      .and(qa.bitwiseAnd(1 << 11).eq(0));
    return image.updateMask(cloudMask);
  }

  const masked = collection.map(maskClouds);
  const image = masked.median();

  // 4. Calculate turbidity using Red band (B4) as proxy for milky/turbid water
  const turbidity = image.select('B4');

  // 5. Extract values at both points
  const stats1 = await turbidity.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point1.buffer(100),
    scale: 10,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await turbidity.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point2.buffer(100),
    scale: 10,
    maxPixels: 1e9
  }).getInfo();

  const val1 = stats1.B4;
  const val2 = stats2.B4;

  console.log(`Point1 (50.28, -58.94) turbidity: ${val1}`);
  console.log(`Point2 (50.42, -54.13) turbidity: ${val2}`);

  // 6. Validation & Final Answer
  if (val1 === null || val1 === undefined) {
    console.log('Point1: No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (val2 === null || val2 === undefined) {
    console.log('Point2: No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (isNaN(val1) || isNaN(val2)) {
    console.log('Calculation failed - NaN result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Higher reflectance in red band indicates more turbid/milky water
  if (val1 > val2) {
    console.log('Point1 is more milky than Point2.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Point1 is NOT more milky than Point2.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
